<?php if(in_array($_SESSION['user']['role'],['admin','teacher'],true)): ?><p><a class="button" href="/products/create">Register product</a></p><?php endif ?>
<div class="cards"><?php foreach($rows as $product): ?><article><h2><?= e($product['name']) ?></h2><?php if($product['image_name']): ?><img class="product-image" src="/products/<?= e($product['id']) ?>/image" alt="<?= e($product['name']) ?>"><?php endif ?><p>Price: <?= e($product['price']) ?></p><p>Quantity: <?= e($product['quantity']) ?></p></article><?php endforeach ?></div><?php if(!$rows): ?><p>No products registered.</p><?php endif ?>
